/* Generated by Trae Work — 周四001-009 赛果复盘 + 投注指南验证图表 */
(function () {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var good = style.getPropertyValue('--good').trim();
  var bad = style.getPropertyValue('--bad').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();

  function baseGrid() {
    return { left: 44, right: 16, top: 36, bottom: 30, containLabel: true };
  }
  function baseTooltip() {
    return {
      backgroundColor: 'rgba(15,23,42,0.92)',
      borderColor: rule,
      textStyle: { color: ink, fontSize: 12 },
    };
  }
  function baseAxis() {
    return {
      axisLine: { lineStyle: { color: rule } },
      axisLabel: { color: muted, fontSize: 11 },
      splitLine: { lineStyle: { color: rule, type: 'dashed' } },
    };
  }

  var labels = ['001\n艾卜哈', '002\n克拉约瓦', '003\n帕福斯', '004\n维京古', '005\n利雅得', '006\n流浪者', '007\n安德莱', '008\n哈茨', '009\n米拉索尔'];

  // ============ 图 1: HAD / HHAD / 投注指南 命中分布 ============
  var hadHit = [0, 1, 0, 1, 1, 0, 1, 0, 0];
  var hhadHit = [1, 0, 1, 0, 1, 0, 1, 0, 0];
  var guideHit = [1, 1, 1, 0, 1, 0, 1, 0, 0];

  var chart1 = echarts.init(document.getElementById('chart-hit'), null, { renderer: 'svg' });
  chart1.setOption({
    animation: false,
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var idx = params[0].dataIndex;
        var had = hadHit[idx] ? '✓ 命中' : '✗ 未中';
        var hhad = hhadHit[idx] ? '✓ 命中' : '✗ 未中';
        var guide = guideHit[idx] ? '✓ 命中' : '✗ 未中';
        return '<b>' + labels[idx].replace('\n', ' ') + '</b><br/>' +
          'HAD: <span style="color:' + (hadHit[idx] ? good : bad) + '">' + had + '</span><br/>' +
          'HHAD: <span style="color:' + (hhadHit[idx] ? good : bad) + '">' + hhad + '</span><br/>' +
          '投注指南: <span style="color:' + (guideHit[idx] ? good : bad) + '">' + guide + '</span>';
      },
    }),
    legend: {
      data: ['HAD 方向', 'HHAD 让球', '投注指南'],
      textStyle: { color: muted, fontSize: 11 },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: labels,
      axisLabel: { color: muted, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0, max: 1, interval: 0.5,
      splitLine: { show: false },
      axisLabel: { color: muted, fontSize: 11, formatter: function (v) { return v === 1 ? '命中' : '未中'; } },
    }),
    series: [
      {
        name: 'HAD 方向',
        type: 'bar',
        data: hadHit,
        barWidth: 16,
        barGap: '25%',
        itemStyle: {
          color: function (p) { return p.value === 1 ? good : bad; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
      {
        name: 'HHAD 让球',
        type: 'bar',
        data: hhadHit,
        barWidth: 16,
        itemStyle: {
          color: function (p) { return p.value === 1 ? accent : 'rgba(148,163,184,0.3)'; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
      {
        name: '投注指南',
        type: 'bar',
        data: guideHit,
        barWidth: 16,
        itemStyle: {
          color: function (p) { return p.value === 1 ? accent2 : 'rgba(148,163,184,0.3)'; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
    ],
  });

  // ============ 图 2: 投注指南档位命中率对比 ============
  var chart2 = echarts.init(document.getElementById('chart-guide'), null, { renderer: 'svg' });
  chart2.setOption({
    animation: false,
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      formatter: function (params) {
        var p = params[0];
        return '<b>' + p.name + '</b><br/>命中率: <span style="color:' + accent + ';font-size:16px;font-weight:700">' + p.value + '%</span><br/>' +
          '场次: ' + (p.name === '✅ 单选' ? '2/5' : (p.name === '⚠️ 双选兜底' ? '3/4' : '5/9'));
      },
    }),
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: ['✅ 单选', '⚠️ 双选兜底', '📊 总命中'],
      axisLabel: { color: muted, fontSize: 12, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0, max: 100,
      axisLabel: { color: muted, fontSize: 11, formatter: '{value}%' },
    }),
    series: [{
      type: 'bar',
      data: [
        { value: 40, itemStyle: { color: bad, borderRadius: [6, 6, 0, 0] } },
        { value: 75, itemStyle: { color: good, borderRadius: [6, 6, 0, 0] } },
        { value: 55.6, itemStyle: { color: accent, borderRadius: [6, 6, 0, 0] } },
      ],
      barWidth: 60,
      label: { show: true, position: 'top', color: ink, fontSize: 14, fontWeight: 700, formatter: '{c}%' },
      markLine: {
        silent: true,
        symbol: 'none',
        lineStyle: { color: muted, type: 'dashed', width: 1 },
        label: { color: muted, fontSize: 10, formatter: '盈亏线 50%' },
        data: [{ yAxis: 50 }],
      },
    }],
  });

  // ============ 图 3: 平局击穿分析 — 单选翻车 vs 双选覆盖 ============
  var chart3 = echarts.init(document.getElementById('chart-draw'), null, { renderer: 'svg' });
  var drawLabels = ['001\n客胜', '002\n主胜', '003\n平局', '004\n主胜', '005\n客胜', '006\n平局', '007\n主胜', '008\n平局', '009\n平局'];
  var isDraw = [0, 0, 1, 0, 0, 1, 0, 1, 1];
  var guideOk = [1, 1, 1, 0, 1, 0, 1, 0, 0];
  var guideType = ['cover', 'single', 'cover', 'cover', 'single', 'single', 'cover', 'single', 'single'];

  chart3.setOption({
    animation: false,
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var idx = params[0].dataIndex;
        var draw = isDraw[idx] ? '平局' : '非平局';
        var gOk = guideOk[idx] ? '✓ 命中' : '✗ 击穿';
        var gType = guideType[idx] === 'single' ? '✅ 单选' : '⚠️ 双选兜底';
        return '<b>' + labels[idx].replace('\n', ' ') + '</b><br/>' +
          '赛果: <span style="color:' + (isDraw[idx] ? accent2 : ink) + '">' + draw + '</span><br/>' +
          '指南: <span style="color:' + (guideOk[idx] ? good : bad) + '">' + gType + ' ' + gOk + '</span>';
      },
    }),
    legend: {
      data: ['平局', '指南命中'],
      textStyle: { color: muted, fontSize: 11 },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: drawLabels,
      axisLabel: { color: muted, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0, max: 1, interval: 0.5,
      splitLine: { show: false },
      axisLabel: { color: muted, fontSize: 11, formatter: function (v) { return v === 1 ? '是' : ''; } },
    }),
    series: [
      {
        name: '平局',
        type: 'bar',
        data: isDraw,
        barWidth: 16,
        barGap: '25%',
        itemStyle: {
          color: function (p) { return p.value === 1 ? accent2 : 'rgba(148,163,184,0.15)'; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return p.value === 1 ? '平' : ''; } },
      },
      {
        name: '指南命中',
        type: 'bar',
        data: guideOk,
        barWidth: 16,
        itemStyle: {
          color: function (p) { return p.value === 1 ? good : bad; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
    ],
  });

  window.addEventListener('resize', function () {
    chart1.resize();
    chart2.resize();
    chart3.resize();
  });
})();